#include <cstddef>
#include <unordered_set>

struct Hash {
  std::size_t operator()(int x) const { return static_cast<std::size_t>(x); }
};
struct Eq {
  bool operator()(int a, int b) const { return a % 10 == b % 10; }
};

int main() {
  std::unordered_set<int, Hash, Eq> s;
  s.insert(1);
  s.insert(11);
}

